from html.parser import HTMLParser
import collections, json
class P(HTMLParser):
    def __init__(self): super().__init__(); self.in_meta=False; self.buf=''; self.scripts=[]; self.article_tags=0
    def handle_starttag(self, tag, attrs):
        attrs=dict(attrs)
        if tag=='script':
            if attrs.get('id')=='article-meta': self.in_meta=True
            if attrs.get('src'): self.scripts.append(attrs.get('src'))
        if attrs.get('class') and 'article-tags' in attrs.get('class').split(): self.article_tags+=1
    def handle_data(self, data):
        if self.in_meta: self.buf+=data
    def handle_endtag(self, tag):
        if tag=='script' and self.in_meta: self.in_meta=False
